-- 1) Creación de la tabla
create table if not exists public.jugadores (
  id bigint generated by default as identity primary key,
  posicion_categoria text not null,
  nombre_apellidos text,
  fecha_nacimiento date,
  puesto text,
  lateralidad text,
  talla_cm numeric,
  talla_raw text,
  categoria text,
  equipo_actual text,
  temporada_25_26 text,
  temporada_24_25 text,
  temporada_23_24 text,
  temporada_22_23 text,
  nivel_estimado text,
  caracteristicas_ataque text,
  caracteristicas_defensa text,
  fila_excel int,
  created_at timestamptz default now()
);

-- Nota: esta tabla se creó con Row Level Security (RLS) activado y sin
-- políticas todavía, por lo que solo es accesible desde el SQL Editor /
-- con una clave "secret" de Supabase (bypassa RLS). Si más adelante quieres
-- leerla desde una app con la clave pública, habrá que añadir políticas.

