insert into public.jugadores (posicion_categoria, nombre_apellidos, fecha_nacimiento, puesto, lateralidad, talla_cm, talla_raw, categoria, equipo_actual, temporada_25_26, temporada_24_25, temporada_23_24, temporada_22_23, nivel_estimado, caracteristicas_ataque, caracteristicas_defensa, fila_excel) values
('PORTEROS', '1.José Javier Belman Calvo', '1998-10-04', 'Portero', 'Diestro', 185, 185, '1ªRFEF', NULL, 'TALAV (16 PT -14 GC) 1ªRFEF', 'IBIZA (9PT -11GC) 1ª RFEF', 'FUENLA (37 PT -35) 1ªRFEF', 'LEGANÉS (0´)2ª', 'ALTA TABLA', 'Características ataque:  Buen juego de pies. LIDERAZGO Y COMUNICATIVO.  Sabe jugar y atraer la presión del rival para encontrar al hombre libre. Capacidad para el juego interior. Gran juego de pies.', 'Características defensa: Buen posicionamiento y con poco trabajo.', 2),
('PORTEROS', 'Javier Navarro Jiménez', '2007-01-25', 'Portero', 'Diestro', 186, 186, '1ª-2ªRF-JDH', NULL, '(2500´ -23 G)', 'ÍDEM (1700´)', 'JNC Y JUV C(1500´)', NULL, 'ALTA TABLA', NULL, NULL, 5),
('PORTEROS', 'Diego Barrios Pérez', '1994-07-30', 'Portero', 'Diestro', 187, 187, '2ªRFEF', NULL, '(2489´ -36 G)', 'Anto (3150´ -34G)', 'VELEZ (1150´, -17)', 'VELEZ (990´, -16)', 'MEDIA TABLA', 'Características ataque: Buen uso del pie diestro para encontrar a jugadores cercanos. Es un portero valiente desde la portería y se atreve a conectar con laterales o interiores.', 'Características defensa: Gran 1vs1, es capaz de aguantar hasta el último momento y no girar el cuerpo. Sufre fuera palos, ya que no tiene una gran talla.', 8),
('PORTEROS', 'Dani Alcover Pedrón', '2004-04-03', 'Portero', 'Diestro', 185, 185, '1ªRFEF', NULL, '(2543´ , -35G)', 'Ante (90´)', 'Roda 3ª (1509´, -18G)', 'VILL DH (1350´)', 'MEDIA TABLA', NULL, NULL, 11),
('LATERALES DCHO', 'Manu Sánchez García', '1996-03-24', 'Lateral dcho, extremo dere', 'Diestro', 183, 183, '1ªRFEF', NULL, 'CEUTA (3PT, 2G)', 'LEV (3PT)2ª DIV', 'CASTE (32 PT ,8G)', 'CASTE (41, 11G)', 'ALTA TABLA', 'Características ataque: Despliegue y capacidad para llegar a línea de fondo con facilidad. Muy rápido y con gran capacidad para acelerar.', 'Características defensa: Buen nivel defensivo.  Gran capacidad para acelerar y actitud defensiva, difícil de superar en el 1vs1.', 2),
('LATERALES DCHO', 'Mario Navarro García', '2008-02-22', 'Lateral derecho', 'Diestro', 187, 187, '2ªRFEF', NULL, 'BETIS JDH (27 PT 3G)', 'CAL (32 PJ 2G)', 'BET JN (25PJ 2G)', NULL, 'ALTA TABLA', 'Características ataque: Muy dinámico y con capacidad para desbordar en conducción a rivales. Buena conducción y capacidad para asociarse, supera rivales con facilidad. Buena talla para ser lateral, es muy rápido.', 'Características defensa: No es su mejor característica pero tiene buena talla para el juego aéreo defensivo.', 5),
('LATERALES DCHO', 'Jose A. Molina Palma', '2005-03-11', 'Lateral derecho', 'Diestro', 165, 165, '3ªRFEF', NULL, '3ªRFEF (32 PJ)', '3ªRFEF (19 PJ)', 'Marbella FC DH (32 PJ)', NULL, 'ALTA TABLA', 'Características ataque. Jugador muy rápido que destaca por su profundidad, dominio del control-pase y rupturas. Tiene bue pie para dar centros y tiene criterio con balón', 'Características defensa. No destaca por juego aéreo, buen 1vs1 defensivo, rápido en transiciónes defensivas y se sacrifica por el equipo.', 8),
('LATERALES DCHO', 'Jesús Fortea Tejedo', '2007-03-26', 'Lateral derecho', 'Diestro', 168, 168, '1ªRFEF', NULL, '1ªRFEF', '1ªRFEF (1080´)', '2ªRF+JDH (2200´ 3G)', 'JDH (2045´)', 'ALTA TABLA', NULL, NULL, 11),
('LATERALES IZQDO', 'David Serrano Cortés', '2005-01-28', 'Lateral izquierdo', 'Zurdo', 182, 182, '1ªRFEF', NULL, '1ªRFEF', '2ªRFEF (37 PT)', '3ª RFEF (15 PT)', 'DH (5PT)', 'MEDIA-BAJA TABLA', 'Características ataque: Jugador de calidad con pierna izquierda, capacidad para relacionarse encontrando a jugadores por dentro. Capacidad para la conducción y superar rivales. Se incorpora al ataque con asiduidad', 'Características defensa: No es su mayor fuerza pero tiene nociones defensivas. Difícil de desbordar desde parado, en movimiento sufre más por que no es rápido.', 2),
('LATERALES IZQDO', 'David Argüelles Álvarez', '2002-01-10', 'Lateral izquierdo', 'Zurdo', 175, 175, '2ªRFEF', NULL, '2ªRFEF', '2ªRF LEALTAD (1317´)', '2ªR GET B (954´)', '1ªR IBIZA (224´)', 'MEDIA TABLA', NULL, NULL, 5),
('CENTRAL DCHO', 'Javier Mérida Palomino', '1996-01-18', 'Central izquierdo, diestro.', 'Diestro', 179, 179, '1ªRFEF', NULL, 'TORREM (25 PT, 3G) 1ªRF', 'TORREM (24 PT, 2G) 2ªRF', 'TORREM (21 PT, 3G) 3ªR', 'EL EJID (21 PT, 1G) 2ªR', 'MEDIA TABLA', NULL, NULL, 2),
('CENTRAL DCHO', 'Alejandro Pérez Cea', '2001-01-07', 'Central diestro', 'Diestro', 180, 180, '2ªRFEF', NULL, '2ªRF ISL. BALLE(3426´)', '2ªRF CORNELLA (2468´)', '2ªRF ESPAÑOL B (1046´)', '2ªRF ESPÑB (720´)', 'MEDIA TABLA', 'Características ataque: Gran capacidad para la conduccion y el cambio de orientación. Tiene más capacidad de la que demuestra jugando. Es un jugador a muy tener en cuenta porque es joven y tiene mucho criterio. Necesita mejorar la pierna izquierda.', 'Características defensa: Muy inteligente a nivel táctico, puesto que no es muy rápido y llega muy bien a la anticipacion y a la defensa fuera de puesto especifico.', 5),
('CENTRAL DCHO', 'Alberto M. Quintana Moreno', '2001-10-05', 'Central diestro, izqdo y Mediocentro.', 'Diestro', 186, 186, '1ªRFEF', NULL, '1ª RF (3076´)', '1ªRF IRÚN (3051´)', '2ª VALL (424´ 1G) 2ºRF (1530´ 1G)', '2ªRF VALL (2580´)', 'MEDIA TABLA', 'Características ataque: Jugador que ha jugado mucho tiempo en el centro del campo con mucha capacidad para jugar con pocos contactos. Buena capacidad para relacionarse y buen uso del cambio de orientacion. Juega sencillo y no comete errores de bulto.', 'Características defensa: Gran juego aéreo y muy difícil de superar a nivel individual. Es un jugador de equipo que llega muy bien a las coberturas. Muy resistente y sacrificado.', 8),
('CENTRAL DCHO', 'Badofe', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 11),
('CENTRAL IZQDO', 'Jean Emmanuel Ngoran', '2007-01-01', 'Central izqdo, lateral izqdo.', 'Zurdo', 187, 187, '2ªRFEF', NULL, '1ªRFEF (840´ 1G)- Juv Dh', 'JUV DH (172´)', NULL, NULL, 'ALTA TABLA', 'Características ataque: Gran desplazamiento para mirar lejos y realizar cambios de orientación. Mucha capacidad para la conducción y progresar superando línea de presión.', 'Características defensa: Muy agresivo y con capacidad para la anticipación. Muy bien en la defensa hacia delante y hacia atrás.', 2),
('CENTRAL IZQDO', 'Carlos Becken Alcalde', '2002-01-01', 'Central izquierdo', 'Zurdo', 185, 185, '2ªRFEF', NULL, '2ªRFEF (2400´ 2G)', '1ªRF RECRE (1128´)', '2ªS ROQUE (2096´)', 'DH LA PALMA (2400´)', 'MEDIA TABLA', NULL, NULL, 5),
('MEDIOCENTRO', 'José Álvarez Martíi', '2000-08-24', 'Mediocentro', 'Diestro', 177, 177, '1ªRFEF', NULL, '2ªRFEF (2061´)', '2ªRFEF-CONQ (2122´)', '2ªR AT-SAG (1702´)', '2ªR AT SAG (912´)', 'MEDIA TABLA', 'Características ataque: Dinámico y con capacidad para recibir dentro. Muy activo en su posición y con velocidad para dar desmarques en último tercio. Participativo y con criterio en juego asociativo.', 'Características defensa: solidario y con mucha presencia defensiva. Inteligente a nivel táctico.', 2),
('MEDIOCENTRO', 'Mario García Parada', '1997-07-23', 'Mediocentro', 'Diestro', 174, 174, '1ªRFEF', NULL, '1ªRFEF ZAMORA (1813´ 4G)', '1ªR HÉRC (1697´)', '1ª ALGEC (2376´ 2G)', '1ª R.MAJAD (2155´)', 'ALTA TABLA', 'Características ataque: Jugador aseado con balón pero no tiene una gran capacidad para asociarse. Muy correcto en su juego y hace llegar a los jugadores cercanos. Gran capacidad para el juego aéreo defensivo y ofensivo. Tiene mucha presencia con balón.', 'Características defensa: Gran capacidad para jugar sin balón y realizar grandes esfuerzos. Tiene mucha presencia sin balón, tiene gran capacidad para la anticipación y un gran juego aéreo defensivo.', 5),
('MEDIOCENTRO', 'Iván Romero Vega', '2003-08-01', 'Mediocentro', 'Diestro', 182, 182, '2ªRFEF', NULL, '2ªRFEF (1573´)', '3ªRFEF (2470´. 3G)', 'UTRERA (2540´ 2G)', 'GERENA (148´)', 'MEDIA TABLA', NULL, NULL, 8),
('MC AVANZADOS', 'Cristian Rodríguez Pérez', '1996-03-15', 'Interior, mediapunta.', 'Diestro', 183, 183, '1ªRFEF', NULL, 'CEUTA (5 PT, 1 G)', 'CEUTA (14 PT, 3 G)', 'CEUTA-CAST (24 PT, 3G)', 'CASTE (38 PT, 3G)', 'ALTA TABLA', 'Características ataque: Gran capacidad para tener el balón. Talento asociativo y precisión en el desplazamiento del balón. Experto a balón parado', 'Características defensa: Agresivo y no le gusta no tener balón. No es su mejor característica.', 2),
('MC AVANZADOS', 'Dominique Moubeke', '2005-08-11', 'Interior o pivote', 'Zurdo', 182, 182, '1ªRFEF', NULL, 'REC GCF (8 PT, 3 G) 3ª', 'CORIA (8PT, 1 G) 2ªR', 'MORALO B (4 PT) 1ªEXT', 'MORALO JN (PT 1)', 'MEDIA-BAJA TABLA', 'Características ataque: Gran dominio de la pierna izquierda. Capacidad para driblar y superar jugadores en conducción. Buen último pase y buena incorporación al ataque.', 'Características defensa: Poco sacrificado. No sabe defender y comete muchas faltas. Necesita mejorar.', 5),
('MC AVANZADOS', 'Paolo  Romero Mongue', '2005-02-12', 'Interior o extremo izqdo', 'Diestro', 175, 175, '2ªRFEF', NULL, '2ªRFEF (2831, 2G)', '1ªRFEF (1520´', 'DH SEN (2000´, 7G)', 'JUV DH (2543´ 9G)', 'MEDIA-ALTA TABLA', 'Características ataque: Mediapunta con mucha capacidad para recibir entre líneas y acelerar el juego. Sabe recibir con presión y tiene mucha llegada al área. Destaca por ser capaz de relacionarse con los compañeros. Tiene experiencia ya que lleva varias temporadas jugando con séniors.', 'Características defensa: solidario y trabajador. Es un jugador que destaca su intensidad sin balón y trabajo al servicio del equipo.', 8),
('MC AVANZADOS', 'Iván Correlajo Mantero', '2007-05-01', 'Interior o extremo izquierdo', 'Diestro', 176, 176, '1ª RFEF - JUV DH', NULL, '1ªRFEF-JUV DH (2400´ 3G)', 'JUV DH (1559´ 5G)', 'JUV DH (2371´ 5G)', NULL, 'MEDIA-ALTA TABLA', 'Características ataque: Talento con balón sobresaliente que le hace dominar muy bien la recepción del mismo para girar sobre sí mismo. Se posiciona bien entre líneas y encuentra muy bien a los compañeros. Necesita usar más la izquierda.', 'Características defensa: No destaca por su capacidad defensiva, pero es un jugador con mucha ambición y su deseo de balón le hace activarse bien tras pérdida.', 11),
('MC AVANZADOS', 'Manuel Sarmiento Cantarero', '1997-06-16', 'Interior o media punta', 'Zurdo', 173, 173, '3ªRFEF', NULL, '3ªRFEF', '3ªRFEF', '3ªRFEF', '3ªRFEF', 'MEDIA-BAJA TABLA', NULL, 'Características defensa. Jugador sacrificado que se activa tras pérdida, es solidario con el equpo.', 14),
('MC AVANZADOS', 'Mario Martos Serrano', '1991-11-14', 'Mediapunta', 'Diestro', 175, 175, '1ªRFEF', NULL, '2ªRFEF (2913´ 7G)', '3ªRF(1645´, 4G)', '3ªRF(2419´, 9G)', '3ªRF(2275´, 8G)', 'MEDIA-BAJA TABLA', 'Características ataque: Jugador que se posiciona bien en el úlitmo tercio. Especialista a balón parado y con una gran pegada. Tiene mucho gol.', 'Características defensa: Jugador muy intenso y con mucho carácter.', 17),
('MC AVANZADOS', 'Samuel Expósito', '2004-08-07', 'Mediapunta', 'Diestro', 162, 162, '2ªRFEF', NULL, '2ªRFEF (30 PJ)', '3ªRFEF (11 PJ)', '1ªRFEF (15 PJ)', '2ªRFEF (4 PJ)', 'ALTA TABLA', 'Características ataque. Jugador que sabe moverse entre líneas, muy dinámico, con gran visión de juego, 1vs1 y mucho criterio con balón.', 'Características defensa. Buena activación en la presión tras pérdida, bien en la presión alta y se sacrifica por el conjunto.', 20),
('MC AVANZADOS', 'Juan Jesús Rodríguez Rdgz (Juanje)', '2000-06-09', 'Interior o pivote', 'Diestro', 179, 179, '1ªRFEF', NULL, '1ªRFEF (3209´ 3G)', '1ªRF YEC (2500´ 3G)', '2ªRF YEC (2400´ 3G)', '2ªRF MREAL (1600´ 3G)', 'ALTA TABLA', 'Características ataque: Jugaador experto para jugar entre líneas. Sabe recibir presionado y girar muy bien sobre sí mismo. Jugador muy resistente y llegador al área. Muy dinámico y necesita entrar en contacto con el balón.', 'Características defensa: Muy intenso y trabajador. No es desbordado fácilmente y si es superado llega de nuevo a su posicionamiento. Hábil en la presión en bloque alto y resistente para realizar grandes esfuerzos.', 23),
('MC AVANZADOS', 'Manex Rezola Iruretagoyena', '2006-11-21', 'Interior o pivote', 'Zurdo', 185, 185, '2ªRFEF', NULL, 'LOGROÑÉS 1400´+RM"C"1300´', '(2400´ 8G)', 'VASCONIA (1400´4G)', NULL, 'MEDIA-BAJA TABLA', 'Características ataque: Gran dominio del balón y protección del mismo. Sabe ubicarse entre líneas y recibir en movimiento, muy dinámico. Encuentra a compañeros de forma asociativa con relativa facilidad. Jugador de una capacida asociativa excelente, tiene una templanza que le permite decidir bien en momento de estrés.', 'Características defensa: Sacrificado y con presencia defensiva. Debe mejorar en duelos y en agresividad para dar un paso más hacia el fútbol profesional. Jugador muy resistente.', 26),
('MC AVANZADOS', 'Dylan José Pereira Plasencia', '2003-05-11', 'Interior', 'Zurdo', 175, 175, '2ªRFEF', NULL, '2ªRF (1607´, 1G)', '2ªRF (1137´, 1G)', '3ªRF (1741, 5G)', '3ªRF (1033)', 'MEDIA-BAJA TABLA', 'Características ataque: Dinámico, habilidoso y con gran capacidad para asociarse. Tiene mucho talento para jugar entre líneas y un gran disparo lejano. Será un jugador muy importante en esta plantilla y al ser su últiimo año sub23 tendrá un papel muy importante en la plantilla.', 'Características defensa: No es su mejor caracteristica pero es agresivo, se percibe perfectamente que lo pasa mal sin balón por lo cual es agresivo tras pérdida.', 29),
('MC AVANZADOS', 'Seydina Moha Bassele', '2000-01-01', 'Interior', 'Zurdo', 180, 180, '1ª RFEF', NULL, '1ªRF(1900´, 10G)', '2ªRF MELI (1060´ 3G)', '3ªREF LAS PALM (480´ 1G)', NULL, 'ALTA TABLA', 'Características ataque: Dinámico, con calidad individual para proteger el balón y para relacionarse. Interior de calidad y que puede jugar en categorias superiores. Capacidad para jugar entre líneas y para llegar al área.', 'Características defensa: Tiene presencia sin balón y capacidad física para defender en alto nivel, aunque su carácter es un poco frío y necesita dar un plus más en este sentido.', 32),
('MC AVANZADOS', 'Lacosta', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35),
('EXTREMOS DCHO', 'Rafa Oya Mesa', '2008-03-31', 'Extremo derecho', 'Zurdo', 179, 179, '2ªRFEF', NULL, 'Juvenil DH (1826´, 10G)', 'CALA (2370´, 3G)', 'DH CAD (24PT, 18G)', NULL, 'MEDIA-BAJA TABLA', 'Características ataque: juega a pierna cambiada y es un jugador que destaca por su 1vs1. Sabe relacionarse y hace girar el equipo propio para atacar el lado libre. Llega bien al área y destaca su capacidad para el gol.', 'Características defensa: no destaca en este sentido y necesita mejorar mucho.', 2),
('EXTREMOS DCHO', 'Diego Fuentes Pérez(Chino)', '2003-09-01', 'Extremo derecho', 'Zurdo', 172, 172, '1ªRFEF', NULL, '2ªRF. R.Cantabria ()', NULL, NULL, NULL, NULL, 'Características ataque: Jugador que me ha soprendido el gran nivel ofensivo que tiene cuando posee el balón. Gran proteccion del balon, capacidad para girar y para relacionarse. Es jugador de pie, a pesar de ser veloz, aspecto que podria ganar para aumentar su bagaje ofensivo.', 'Características defensa: Sacrificado y trabajador, aunque necesita una mejora física grande para ser un jugador de valor en la élite.', 5),
('EXTREMOS DCHO', 'Pau Mascaró Ruiz', '2004-01-01', 'Extremo derecho', 'Zurdo', 178, 178, '2ªRFEF', NULL, 'PORRERES+RAYO CANT(2500´ 19G)', 'MALLORCA B-2RF (1800´ 3G)', 'MALLORCA B 3R(2500´ 14G)', NULL, 'MEDIA-ALTA TABLA', 'Características ataque: Jugador de alta habilidad que le hace ser muy determinante cuando recibe el balón. Capacidad de encontrar a compañeros a través de pases interiores o de girar el juego.. Tiene alta capacidad para desbordar rivales. Llegador al área rival.', 'Características defensa: Necestia mejorar en este registro si quiere dar un salto al fútbol profesional. No es su mejor característica.', 8),
('EXTREMOS DCHO', 'J.M. López López. Juanmita', '2002-06-23', 'Extremo derecho', 'Zurdo', 170, 170, '2ªRFEF', NULL, '(717´ 1G)', 'LESIONADO', '(1436´, 2G)', 'AT.MALA (2016´ 6G)', 'MEDIA-ALTA TABLA', 'Características ataque: Jugador de un talento con balón altísimo. Capacidad para el 1vs1 y para retener el balón ante presión. Sabe relacionarse muy bien y se desenvuelve  mejor en banda derecha a pierna cambiada.', 'Características defensa: Es intenso y perfecto para el press tras pérdida agresivo. Pero tiene deficiencias sin balón para defender en bloque bajo, con lo cual, debería esforzarse mucho más.', 11),
('EXTREMOS DCHO', 'Cristian Montes López', '1997-08-10', 'Extremo derecho', 'Zurdo', 163, 163, '1ªRFEF', NULL, '1ªRFEF Tenerife (383´)', 'ELDENSE 2ª (346´)', 'ELDENSE 2ª (1096´ 1G)', 'ELDENSE 1ªR 2273´ 8G)', 'MEDIA-ALTA TABLA', 'Características ataque: Ya ha jugador en segunda división, con lo cual, demuestra que tiene muchas características ofensivas para jugar a pierna cambiada y generar mucho peligro. Sabe relacionarse y hacer girar el juego del equipo rival. Tiene muy buen último pase y llega con peligro al área.', 'Características defensa: Jugador intenso y trabjador, aunque físicamnete no es un jugador que destaque para realizar esfuerzos defensivos durante los 90´.', 14),
('EXTREMOS DCHO', 'Algassimo Quicala Bari', '2002-02-18', 'Extremo derecho', 'Diestro', 177, 177, '1ªRFEF', NULL, '1ªRFEF R.Avilés (1701´ 5G)', '2ªRFEF R.Cantabria (1301´ 3G)', '2ªR ATH B R.CANT (900´ 3G)', '1ªRF (389´)', 'MEDIA-ALTA TABLA', 'Características ataque: Jugador de una calidad para progresar con balón importante y driblar jugadores. Muy desequilibrante y con buen último pase. Tiene talento para jugar por dentro pero tambien tiene capacidad para jugar por fuera.', 'Características defensa: Nivel físico sin balón para jugar en la élite, si llega a ser un jugador sacrificado le veo jugando muchos partidos en segunda division.', 17),
('EXTREMOS DCHO', 'Diego Gómez Pérez', '2004-07-31', 'Extremo derecho', 'Zurdo', 177, 177, '1ªRFEF', NULL, '1ªRFEF PONTE-CARTA (200´ 1G)', 'ARENT-DÉPOR (2100´ 2G)', '2ªRFEF DEP.FABRIL (1413´)', '3ªR (2500´6G)', 'ALTA TABLA', 'Características ataque: Capacidad para el desborde desde la banda e incrustarse por dentro. Muy desequilibrante y con capacidad para el 1vs1. Tiene capacidad para asociarse y para el último pase.', 'Características defensa: Debe mejorar mucho sin balón aunque es sacrificado. Su físico está aún por desarrollar para poder realizar partidos completos en la élite.', 20),
('EXTREMOS DCHO', 'Manu Vila Cabezas', '2006-03-06', 'Extremo o interior', 'Diestro', NULL, NULL, '2ªRFEF G2', NULL, '2ªRF TUD (1162´3G)', '3ªRF CASTELLÓN B (1000´)', 'BARÇA NC (1900´ 6G)', 'BARÇA NC (116´ 4G)', 'MEDIA-ALTA TABLA', 'Características ataque: Extremo habilidoso que tiene una gran actitud para reactivarse tras pérdida y se caracteriza por su movilidad. Interpreta muy bien las rupturas y sabe asociarse. Es un jugador muy importante y tendrá un papel relevante en la plantilla.', 'Características defensa: Reactivo tras pérdida y veloz para apretar tras pérdida. No le gusta no tener el balón.', 23),
('EXTREMOS DCHO', 'Sergio Castellón', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 26),
('EXTREMOS IZQDO', 'Moha Keita', '1999-09-18', 'Extremo izquierdo', 'Diestro', 167, 167, '1ª RFEF', NULL, '2ª RFEF (31 PT 12 G)', '2ªRFEF (8 PT 2G)', '1ºRFEF (1443´ 2G)', '2ªRFEF (2443´ 7G)', 'MEDIA-BAJA TABLA', 'Características ataque: Muy dinámico y con mucha capacidad para el juego interior. Se asocia bien por dentro realizando juego con 3º. Muy rápido con el balón en los pies y gran pegada desde fuera del área.', 'Características defensa: Sacrificado en defensa. Realiza bien los 2vs2 banda.', 2),
('EXTREMOS IZQDO', 'Óscar Lozano Folgoso', '1996-06-14', 'Extremo diestro', 'Diestro', 164, 164, '1ªRFEF', NULL, '2ª RFEF (293´ 1G)', '3ª RFEF (2833´ 16G)', '3ª RFEF (1980, 7G)', '3ªRFEF (1758´ 6G)', 'MEDIA-BAJA TABLA', 'Características ataque: Juega a pierna cambiada. Destaca por su velocidad y 1vs1. Muy rápido y vertical para llegar a línea de fondo.', 'Características defensa: No es su mayor virtiud. Suele jugar más avanzado para aprovechar su velocidad en transicones ofensivas debido a su velocidad y capacidad para el 1vs1.', 5),
('EXTREMOS IZQDO', 'Tiziano Diego González Martínez', '2007-01-01', 'Extremo izquierdo', 'Diestro', NULL, '--', '3ªRFEF', NULL, 'JDH (1500´ 5G)', 'JNAC PUERTO MG (800´ 2G)', '---', '----', 'MEDIA-ALTA', 'Características ataque: Jugador que sabe recibir entre líneas. Tiene alta capacidad para el gol y es rápido en los últimos metros. Gran 1vs1 y velocidad en los últimos metros.', 'Características defensa: Necesita mejorar mucho en este sentido para creer y dar un salto de nivel.', 8),
